"""The `core-ffi` arm's payload dispatcher, beside `Arms` and `PbArms`."""
import javanames as N

HEAD = ("// @generated by ffi/poc/java/gen/generate.py from ffi/schema/shapes.json."
        " Do not edit.\n")


def emit(ir, ns=N.PKG, binding="Binding", facade=None):
    facade = facade or ns
    rows = [(pid, spec) for pid, spec in ir.schema["payloads"].items()
            if spec["root"] in ir.messages]
    o = [HEAD, "package %s;" % ns, ""]
    if facade != ns:
        o.append("import %s.*;" % facade)
        o.append("")
    o += ["/** Payload id -> the `core-ffi` arm's encode and decode. */",
         "public final class FfiArms {",
         "  private FfiArms() {}", "",
         "  public static boolean encodable(String id) {"]
    noenc = [pid for pid, spec in rows if spec.get("interleaved")]
    o.append("    return !(%s);" % " || ".join('id.equals("%s")' % p for p in noenc)
             if noenc else "    return true;")
    o.append("  }")
    o.append("")
    o.append("  /** Returns the entry point's own result: a bench that called")
    o.append("   *  `encodedLength()` to have something the JIT cannot discard would")
    o.append("   *  add one forward crossing per operation to the arm being measured,")
    o.append("   *  which on P1.1 is about 1 percent of the whole encode. */")
    o.append("  public static int encode(%s b, String id, Object o) {" % binding)
    o.append("    switch (id) {")
    for pid, spec in rows:
        root = spec["root"]
        o.append('      case "%s": return b.encode%s((%s) o);' % (pid, root, root))
    o.append('      default: throw new IllegalArgumentException(id);')
    o.append("    }")
    o.append("  }")
    o.append("")
    o.append("  public static Object decode(%s b, String id, byte[] w, int off, int len) {"
             % binding)
    o.append("    switch (id) {")
    for pid, spec in rows:
        o.append('      case "%s": return b.decode%s(w, off, len);' % (pid, spec["root"]))
    o.append('      default: throw new IllegalArgumentException(id);')
    o.append("    }")
    o.append("  }")
    o.append("}")
    o.append("")
    return "\n".join(o)
